import unittest

from solucao import guardar


class TestGuardarUmaChaveNova(unittest.TestCase):
    def test_guarda_a_chave_nova(self):
        """guardar poe a chave nova no dicionario"""
        d = {"a": 1}
        guardar(d, "b", 2)
        self.assertEqual(d, {"a": 1, "b": 2})

    def test_muda_o_valor_da_chave(self):
        """guardar troca o valor quando a chave ja existe"""
        d = {"a": 1}
        guardar(d, "a", 9)
        self.assertEqual(d, {"a": 9})

    def test_guarda_em_dicionario_vazio(self):
        """guardar funciona com o dicionario vazio"""
        d = {}
        guardar(d, "x", 7)
        self.assertEqual(d, {"x": 7})
